--------------DROP TABLE IF EXISTS `auth_rule`;CREATE TABLE `auth_rule`(    `id`          bigint UNSIGNED                                               NOT NULL AUTO_INCREMENT COMMENT '主键',    `scope`       varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci  NOT NULL COMMENT '{backend:后端,frontend:前端}',    `type`        varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci  NOT NULL COMMENT 'backend:{menu,api} frontend:{menu,view,btn}',    `pid`         bigint UNSIGNED                                               NOT NULL DEFAULT 0 COMMENT '父级 id，0 为根',    `name`        varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '名称',    `path`        varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL     DEFAULT NULL COMMENT '后端 api 路径或前端 path 片段',    `method`      varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci  NULL     DEFAULT NULL COMMENT 'HTTP 方法，api 用，如 GET POST *',    `component`   varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL     DEFAULT NULL COMMENT '前端组件路径，view 用',    `icon`        varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL     DEFAULT NULL COMMENT '图标：{ep:ElementPlus图标组件名,url:图片绝对或相对地址}',    `sort`        int                                                           NOT NULL DEFAULT 0 COMMENT '排序',    `status`      tinyint                                                       NOT NULL DEFAULT 1 COMMENT '{1:启用,0:禁用}',    `create_time` datetime                                                      NULL     DEFAULT NULL COMMENT '创建时间',    `update_time` datetime                                                      NULL     DEFAULT NULL COMMENT '更新时间',    PRIMARY KEY (`id`) USING BTREE,    INDEX `idx_scope_pid` (`scope` ASC, `pid` ASC) USING BTREE,    INDEX `idx_scope_status` (`scope` ASC, `status` ASC) USING BTREE) ENGINE = InnoDB  AUTO_INCREMENT = 212  CHARACTER SET = utf8mb4  COLLATE = utf8mb4_unicode_ci COMMENT = '权限规则（后端/前端双域树）'  ROW_FORMAT = Dynamic;-- ------------------------------ Records of auth_rule-- ----------------------------INSERT INTO `auth_rule`VALUES (1, 'backend', 'menu', 0, '后端接口权限', NULL, NULL, NULL, NULL, 0, 1, NULL, NULL);INSERT INTO `auth_rule`VALUES (2, 'backend', 'api', 16, '规则树', 'auth/rule/tree', 'GET', NULL, NULL, 0, 1, NULL, NULL);INSERT INTO `auth_rule`VALUES (3, 'backend', 'api', 16, '规则详情', 'auth/rule/read', 'GET', NULL, NULL, 1, 1, NULL, NULL);INSERT INTO `auth_rule`VALUES (4, 'backend', 'api', 16, '新增规则', 'auth/rule/save', 'POST', NULL, NULL, 2, 1, NULL, NULL);INSERT INTO `auth_rule`VALUES (5, 'backend', 'api', 16, '更新规则', 'auth/rule/update', 'PUT', NULL, NULL, 3, 1, NULL, NULL);INSERT INTO `auth_rule`VALUES (6, 'backend', 'api', 16, '删除规则', 'auth/rule/delete', 'DELETE', NULL, NULL, 4, 1, NULL, NULL);INSERT INTO `auth_rule`VALUES (7, 'backend', 'api', 16, '绑定后端接口', 'auth/rule/bindApis', 'POST', NULL, NULL, 5, 1, NULL, NULL);INSERT INTO `auth_rule`VALUES (9, 'backend', 'api', 17, '角色树', 'auth/role/tree', 'GET', NULL, NULL, 0, 1, NULL, NULL);INSERT INTO `auth_rule`VALUES (10, 'backend', 'api', 17, '角色详情', 'auth/role/read', 'GET', NULL, NULL, 1, 1, NULL, NULL);INSERT INTO `auth_rule`VALUES (11, 'backend', 'api', 17, '新增角色', 'auth/role/save', 'POST', NULL, NULL, 2, 1, NULL, NULL);INSERT INTO `auth_rule`VALUES (12, 'backend', 'api', 17, '更新角色', 'auth/role/update', 'PUT', NULL, NULL, 3, 1, NULL, NULL);INSERT INTO `auth_rule`VALUES (13, 'backend', 'api', 17, '删除角色', 'auth/role/delete', 'DELETE', NULL, NULL, 4, 1, NULL, NULL);INSERT INTO `auth_rule`VALUES (14, 'backend', 'api', 17, '分配前端规则', 'auth/role/assignRules', 'PUT', NULL, NULL, 5, 1, NULL, NULL);INSERT INTO `auth_rule`VALUES (15, 'backend', 'api', 18, '动态菜单', 'menu/menus', 'GET', NULL, NULL, 0, 1, NULL, NULL);INSERT INTO `auth_rule`VALUES (16, 'backend', 'menu', 1, '规则管理', NULL, NULL, NULL, NULL, 400, 1, NULL, '2026-05-14 17:02:23');INSERT INTO `auth_rule`VALUES (17, 'ba