ire_time` (`expire_time` ASC) USING BTREE) ENGINE = InnoDB  AUTO_INCREMENT = 1  CHARACTER SET = utf8mb4  COLLATE = utf8mb4_unicode_ci COMMENT = '登录RSA密钥'  ROW_FORMAT = Dynamic;SET FOREIGN_KEY_CHECKS = 1;